select ok(not (select prosecdef from pg_proc where oid='public.brand_sales_summary(uuid,uuid,date,date)'::regprocedure),'summary respects session RLS as security invoker');
select ok(not has_function_privilege('anon','public.brand_sales_summary(uuid,uuid,date,date)','execute'),'anonymous execution revoked');
